	/**
	 * Prompt user and change password on server (not initiated by user).
	 * @param parent dialog parent
	 * @param handle server handle
	 * @param serverInfo server information
	 * @throws IOException if error occurs while updating password
	 */
	public static void changePassword(Component parent, RepositoryServerHandle handle,
			string serverInfo)
    {
		getClientAuthenticator();
		if (clientAuthenticator == null) {
			return;
		}
		char[] pwd = null;
		try {
			pwd = clientAuthenticator.getNewPassword(parent, serverInfo, handle.getUser());
			if (pwd != null) {
				handle.setPassword(
					HashUtilities.getSaltedHash(HashUtilities.SHA256_ALGORITHM, pwd));
				Msg.showInfo(typeof(ClientUtil), parent, "Password Changed",
					"Password was changed successfully");
			}
		}
		finally {
			if (pwd != null) {
				// Attempt to remove traces of password in memory
				Arrays.fill(pwd, ' ');
			}
		}
	}

	static bool processPasswordCallbacks(Callback[] callbacks, string serverName,
			string defaultUserID, string loginError)
    {
		getClientAuthenticator();
		if (clientAuthenticator == null) {
			Msg.error(typeof(ClientUtil), "Unable to authenticate user without ClientAuthenticator");
			return false;
		}
		NameCallback nameCb = null;
		PasswordCallback passCb = null;
		ChoiceCallback choiceCb = null;
		AnonymousCallback anonymousCb = null;
		foreach (Callback callback in callbacks) {
			if (callback is NameCallback) {
				nameCb = (NameCallback) callback;
				nameCb.setName(defaultUserID);
			}
			else if (callback is PasswordCallback) {
				passCb = (PasswordCallback) callback;
			}
			else if (callback is ChoiceCallback) {
				choiceCb = (ChoiceCallback) callback;
			}
			else if (callback is AnonymousCallback) {
				anonymousCb = (AnonymousCallback) callback;
			}
		}
		if (passCb == null) {
			throw new IOException(
				"Unsupported authentication callback: " + callbacks[0].GetType().getName());
		}
		if (!clientAuthenticator.processPasswordCallbacks("Repository Server Authentication",
			"Repository Server", serverName, nameCb != null, nameCb, passCb, choiceCb, anonymousCb,
			loginError)) {
			return false;
		}
		string name = defaultUserID;
		if (nameCb != null) {
			name = nameCb.getName();
			if (name == null) {
				name = nameCb.getDefaultName();
			}
		}
		Msg.info(typeof(ClientUtil),
			"Password authenticating to " + serverName + " as user '" + name + "'");
		return true;
	}

	static void processSignatureCallback(string serverName, SignatureCallback sigCb)
    {
		try {
			SignedToken signedToken = DefaultKeyManagerFactory
					.getSignedToken(sigCb.getRecognizedAuthorities(), sigCb.getToken());
			sigCb.sign(signedToken.certChain, signedToken.signature);
			Msg.info(typeof(ClientUtil), "PKI Authenticating to " + serverName + " as user '" +
				signedToken.certChain[0].getSubjectX500Principal() + "'");
		}
		catch (Exception e) {
			string msg = e.getMessage();
			if (msg == null) {
				msg = e.toString();
			}
			throw new IOException(msg, e);
		}
	}

	static bool processSSHSignatureCallback(Callback[] callbacks, string serverName,
			string defaultUserID) {
		NameCallback nameCb = null;
		SSHSignatureCallback sshCb = null;
		foreach (Callback callback in callbacks) {
			if (callback is NameCallback) {
				nameCb = (NameCallback) callback;
				nameCb.setName(defaultUserID);
			}
			else if (callback is SSHSignatureCallback) {
				sshCb = (SSHSignatureCallback) callback;
			}
		}
		if (sshCb == null || !clientAuthenticator.isSSHKeyAvailable()) {
			return false;
		}
		if (!clientAuthenticator.processSSHSignatureCallbacks(serverName, nameCb, sshCb)) {
			return false;
		}
		Msg.info(typeof(ClientUtil),
			"SSH Authenticating to " + serverName + " as user '" + defaultUserID + "'");
		return true;
	}

